mapper.select:
select id, name, category3, city, district, subdistrict, road_address as roadAddress, postal_code as postalCode, phone, lat, lon, updated_at as updatedAt, category_id as categoryId from places where category_id = #{categoryId}
and city = #{city}
and district = #{district}
and subdistrict = #{subdistrict}
and name like concat('%', #{keyword}, '%')
and id > #{lastId}
order by id desc limit #{pageSize}
